"""Compare pipeline results across corpora.

Usage:
    python -m kbeval.compare subtitles=results wikipedia=results/wikipedia --out results

Reads scores.csv, sensitivity.csv and top_ngrams.csv from each results
directory and writes corpus_comparison.md (English) and
corpus_comparison.it.md (Italian).
"""

from __future__ import annotations

import argparse
import csv
from pathlib import Path

TEXT = {
    "en": {
        "title": "Corpus comparison",
        "other": "[Italiano](corpus_comparison.it.md)",
        "generated": "Generated by `python -m kbeval.compare`. Do not edit by hand.",
        "ranking": "Ranking",
        "ranking_note": "Score (lower is better), rank, and mean rank when every weight is scaled by a random factor between 0.5x and 1.5x.",
        "layout": "Layout", "score": "score", "rank": "rank", "mean_rank": "mean rank",
        "metrics": "Key metrics",
        "metrics_note": "Percentages of keystrokes, or of in-word key bigrams for SFB and rolls.",
        "letters": "Letter frequencies that differ most",
        "letters_note": "Share of characters, in percent.",
        "char": "Character", "diff": "difference",
        "home": "home row", "sfb": "SFB", "inward": "inward rolls", "outward": "outward rolls",
        "pinky": "pinkies", "left": "left hand",
    },
    "it": {
        "title": "Confronto tra corpus",
        "other": "[English](corpus_comparison.md)",
        "generated": "Generato da `python -m kbeval.compare`. Non modificarlo a mano.",
        "ranking": "Classifica",
        "ranking_note": "Punteggio (più basso = migliore), posizione, e posizione media quando ogni peso è moltiplicato per un fattore casuale tra 0,5x e 1,5x.",
        "layout": "Layout", "score": "punteggio", "rank": "pos.", "mean_rank": "pos. media",
        "metrics": "Metriche principali",
        "metrics_note": "Percentuali delle battute, o dei bigrammi di tasti dentro le parole per SFB e roll.",
        "letters": "Frequenze delle lettere che cambiano di più",
        "letters_note": "Quota dei caratteri, in percentuale.",
        "char": "Carattere", "diff": "differenza",
        "home": "home row", "sfb": "SFB", "inward": "roll verso l'interno", "outward": "roll verso l'esterno",
        "pinky": "mignoli", "left": "mano sinistra",
    },
}

METRICS = [("home_row", "home"), ("same_finger_bigrams", "sfb"), ("roll_inward", "inward"),
           ("roll_outward", "outward"), ("pinky_load", "pinky"), ("left_hand", "left")]


def _read(path: Path) -> list[dict]:
    with open(path, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


def load_run(directory: Path) -> dict:
    scores = {r["layout"]: r for r in _read(directory / "scores.csv")}
    sens = {r["layout"]: float(r["mean_rank"]) for r in _read(directory / "sensitivity.csv")}
    letters = {r["ngram"]: float(r["share"]) for r in _read(directory / "top_ngrams.csv") if r["n"] == "1"}
    order = sorted(scores, key=lambda lid: float(scores[lid]["score"]))
    return {"scores": scores, "sens": sens, "letters": letters,
            "rank": {lid: i + 1 for i, lid in enumerate(order)}}


def _table(header, rows):
    out = ["| " + " | ".join(header) + " |", "|" + "|".join("---" for _ in header) + "|"]
    return out + ["| " + " | ".join(r) + " |" for r in rows]


def render(runs: dict[str, dict], lang: str) -> str:
    t = TEXT[lang]
    names = list(runs)
    first = runs[names[0]]
    layouts = sorted(first["scores"], key=lambda lid: first["rank"][lid])
    lines = [f"# {t['title']}", "", t["other"], "", f"_{t['generated']}_", ""]

    lines += [f"## {t['ranking']}", "", t["ranking_note"], ""]
    header = [t["layout"]]
    for n in names:
        header += [f"{n} {t['score']}", f"{n} {t['rank']}", f"{n} {t['mean_rank']}"]
    rows = []
    for lid in layouts:
        row = [lid]
        for n in names:
            run = runs[n]
            row += [f"{float(run['scores'][lid]['score']):.4f}", str(run["rank"][lid]), f"{run['sens'][lid]:.2f}"]
        rows.append(row)
    lines += _table(header, rows) + [""]

    lines += [f"## {t['metrics']}", "", t["metrics_note"], ""]
    header = [t["layout"]] + [f"{t[label]} ({n})" for _, label in METRICS for n in names]
    rows = []
    for lid in layouts:
        rows.append([lid] + [f"{100 * float(runs[n]['scores'][lid][key]):.1f}" for key, _ in METRICS for n in names])
    lines += _table(header, rows) + [""]

    lines += [f"## {t['letters']}", "", t["letters_note"], ""]
    chars = set().union(*(runs[n]["letters"] for n in names))
    get = lambda n, c: runs[n]["letters"].get(c, 0.0)
    diffs = sorted(chars, key=lambda c: -abs(get(names[-1], c) - get(names[0], c)))[:12]
    rows = [[f"`{c}`"] + [f"{100 * get(n, c):.2f}" for n in names]
            + [f"{100 * (get(names[-1], c) - get(names[0], c)):+.2f}"] for c in diffs]
    lines += _table([t["char"]] + names + [t["diff"]], rows) + [""]
    return "\n".join(lines)


def main(argv=None):
    p = argparse.ArgumentParser(prog="kbeval.compare", description="Compare results across corpora.")
    p.add_argument("runs", nargs="+", help="name=results_directory, e.g. wikipedia=results/wikipedia")
    p.add_argument("--out", type=Path, default=Path("results"))
    args = p.parse_args(argv)
    runs = {}
    for spec in args.runs:
        name, directory = spec.split("=", 1)
        runs[name] = load_run(Path(directory))
    args.out.mkdir(parents=True, exist_ok=True)
    (args.out / "corpus_comparison.md").write_text(render(runs, "en"), encoding="utf-8")
    (args.out / "corpus_comparison.it.md").write_text(render(runs, "it"), encoding="utf-8")
    print(f"Wrote {args.out / 'corpus_comparison.md'}")


if __name__ == "__main__":
    main()
